const sensitivePatterns = {
  tracking: ['fbclid', 'gclid', 'utm_', 'mc_', '_ga', 'msclkid'],
  cookies: ['phpsessid', 'jsessionid', 'sessionid'],
  pii: ['email', 'phone', 'userid', 'customer_id', 'token'],
  analytics: ['_hsenc', '_hsmi', 'mkwid', 'pcrid']
};

const chatInput = $input.first().json.chatInput || '';
const sessionId = $input.first().json.sessionId || '';
let url = chatInput.trim();
if (!/^https?:\/\//i.test(url)) {
  url = 'https://' + url;
}
let isValidUrl = false;
let hasSensitiveData = false;
let foundSensitive = [];
let params = [];

try {
  if (url.match(/^https?:\/\/[^\s]+$/i)) {
    isValidUrl = true;
    const queryString = url.split('?')[1] || '';
    if (queryString) {
      params = queryString.split('&').map(pair => pair.split('=')[0].toLowerCase());
      for (const [category, patterns] of Object.entries(sensitivePatterns)) {
        const matches = params.filter(p =>
          patterns.some(pattern => p.includes(pattern))
        );
        if (matches.length > 0) {
          foundSensitive.push({ category, matches });
        }
      }
      hasSensitiveData = foundSensitive.length > 0;
    }
  }
} catch (error) {
  isValidUrl = false;
}
return {
  url: url,
  isValidUrl: isValidUrl,
  hasSensitiveData: hasSensitiveData,
  sensitiveFindings: foundSensitive,
  chatInput: chatInput,
  sessionId: sessionId
};

