const { PDFDocument, StandardFonts, rgb } = require('pdf-lib');

function sanitize(text) {
  if (!text) return '';
  let t = String(text);
  t = t.replace(/\u202F/g, ' ');
  t = t
    .split('')
    .map(ch => (ch.charCodeAt(0) > 255 ? ' ' : ch))
    .join('');
  return t;
}

// einfache Inline-Markup-Bereinigung: **bold**, __bold__, `code`
function cleanInline(text) {
  if (!text) return '';
  return text
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/__(.*?)__/g, '$1')
    .replace(/`([^`]+)`/g, '$1');
}

// Farbe abhängig vom Text (Ergebnis / Priorität)
function colorForLine(text) {
  const lower = text.toLowerCase();

  if (lower.includes('ergebnis: nicht bestanden')) {
    return rgb(0.8, 0, 0);
  }
  if (lower.includes('ergebnis: bestanden')) {
    return rgb(0, 0.5, 0);
  }
  if (lower.includes('priorität: hoch')) {
    return rgb(0.8, 0, 0);
  }
  if (lower.includes('priorität: mittel')) {
    return rgb(0.9, 0.5, 0);
  }
  if (lower.includes('priorität: niedrig')) {
    return rgb(0.3, 0.3, 0.3);
  }

  return rgb(0, 0, 0);
}

async function run() {
  const item = items[0];
  const data = item.json || {};

  const md = sanitize(data.output || '');

  const pdfDoc = await PDFDocument.create();
  let page = pdfDoc.addPage();
  let { width, height } = page.getSize();

  const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

  let cursorY = height - 40;

  function wrapText(page, text, x, y, opts = {}) {
    const font = opts.font || fontRegular;
    const size = opts.size || 11;
    const color = opts.color || rgb(0, 0, 0);
    const maxWidth = opts.maxWidth || width - 80;
    const lineHeight = opts.lineHeight || size + 3;

    const words = text.split(/\s+/);
    let line = '';

    for (const w of words) {
      const testLine = line ? line + ' ' + w : w;
      const lineWidth = font.widthOfTextAtSize(testLine, size);
      if (lineWidth > maxWidth) {
        page.drawText(line, { x, y, size, font, color });
        y -= lineHeight;
        line = w;
      } else {
        line = testLine;
      }
    }

    if (line) {
      page.drawText(line, { x, y, size, font, color });
      y -= lineHeight;
    }

    return y;
  }

  function ensureSpace(linesNeeded, baseSize = 11) {
    const minY = 40;
    const estimated = baseSize + 4;
    if (cursorY - linesNeeded * estimated < minY) {
      page = pdfDoc.addPage();
      ({ width, height } = page.getSize());
      cursorY = height - 40;
    }
  }

  const lines = md.split(/\r?\n/);

  for (const rawLine of lines) {
    let line = rawLine.trimEnd();

    if (!line.trim()) {
      cursorY -= 6;
      continue;
    }

    // ### Überschriften
    const headingMatch = line.match(/^(#{1,6})\s+(.*)$/);
    if (headingMatch) {
      const level = headingMatch[1].length;
      const text = cleanInline(headingMatch[2]);
      const size = level === 1 ? 16 : level === 2 ? 14 : 13;
      ensureSpace(2, size);
      cursorY = wrapText(page, text, 40, cursorY, {
        font: fontBold,
        size,
        color: rgb(0, 0, 0),
      });
      cursorY -= 4;
      continue;
    }

    // Bullet-Listen
    const bulletMatch = line.match(/^(\s*)[-*]\s+(.*)$/);
    if (bulletMatch) {
      const indent = bulletMatch[1].length;
      const body = cleanInline(bulletMatch[2]);

      // Top-Level-Bullets -> als normale Zeile ohne Bindestrich
      if (indent === 0) {
        const display = body;
        const color = colorForLine(display);

        ensureSpace(2, 11);
        cursorY = wrapText(page, display, 40, cursorY, {
          font: fontRegular,
          size: 11,
          color,
        });
      } else {
        // Eingezogene Bullets bleiben echte Stichpunkte
        const x = 60;              // etwas eingerückt
        const bulletChar = '- ';
        const display = bulletChar + body;
        const color = colorForLine(display);

        ensureSpace(1, 11);
        cursorY = wrapText(page, display, x, cursorY, {
          font: fontRegular,
          size: 11,
          color,
        });
      }

      continue;
    }


    // nummerierte Listen
    const orderedMatch = line.match(/^\s*\d+\.\s+(.*)$/);
    if (orderedMatch) {
      const display = cleanInline(line);
      const color = colorForLine(display);
      ensureSpace(1, 11);
      cursorY = wrapText(page, display, 40, cursorY, {
        font: fontRegular,
        size: 11,
        color,
      });
      continue;
    }

    // normaler Absatz
    const display = cleanInline(line);
    const color = colorForLine(display);
    ensureSpace(2, 11);
    cursorY = wrapText(page, display, 40, cursorY, {
      font: fontRegular,
      size: 11,
      color,
    });
  }

  const pdfBytes = await pdfDoc.save();
  const pdfBase64 = Buffer.from(pdfBytes).toString('base64');

  return [
    {
      json: data,
      binary: {
        report: {
          data: pdfBase64,
          mimeType: 'application/pdf',
          fileName: 'manager-agent-report.pdf',
        },
      },
    },
  ];
}

return run();
